"use strict";
// The turn-end artifact check every plugin with contracts ships as hooks/artifacts.cjs (generated by sync.cjs; edit
// scripts/check/engine/hook.cjs). `start` notes the session's start, `mark` notes the artifacts the model wrote,
// `check` judges them at Stop by the contracts under ./lib/contracts and hands each finding back once.
// It knows no kind: each contract names where its artifacts live in a user's project (`scope`). A contract that sets
// `"shell": false` is scanned after a shell turn only for the files a command of the turn names: an install writes them too,
// and names none. Node built-ins only.
const crypto = require("node:crypto");
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
const host = require("./lib/host.cjs");

const CONTRACTS = path.join(__dirname, "lib", "contracts");
const SAFE_SESSION_ID = /^[A-Za-z0-9_-]{1,128}$/u;
const HOOKS_FOLDER = typeof process.getuid === "function" ? `aidd-hooks-${process.getuid()}` : "aidd-hooks";
const STATE_MAX_AGE_MS = 24 * 60 * 60 * 1000;
const SKIPPED_DIRS = new Set([".git", "node_modules"]);
const WILDCARD = /[*{]/u;
const REF_SUFFIX = ".ref";
const MARK_SUFFIX = ".mark";
const MAX_LINES = 20;

const posix = (file) => file.split(path.sep).join("/");
/** One state folder per installed copy: the real path of this hooks folder, since neither its name nor its parent's tells two plugins or two versions apart. */
const copy = () => crypto.createHash("sha256").update(fs.realpathSync(__dirname)).digest("hex").slice(0, 16);
const sessionOf = (event) => (typeof event.sessionId === "string" && SAFE_SESSION_ID.test(event.sessionId) ? event.sessionId : null);

// ---- state: one folder per user and installed copy in the system temp folder ---------------------------------

/** `<tmpdir>/aidd-hooks-<uid>/<copy>`, or null when it is not this user's alone; created only when `create`. */
function stateFolder(create) {
  const hooks = path.join(os.tmpdir(), HOOKS_FOLDER);
  const own = path.join(hooks, copy());
  return host.ownFolder(hooks, create) && host.ownFolder(own, create) ? own : null;
}

/** Writes beside the file then renames over it: a link planted at the path is replaced, never written through. */
function writeAtomic(file, text) {
  const next = `${file}.${process.pid}.${Date.now()}`;
  fs.writeFileSync(next, text, { flag: "wx", mode: 0o600 });
  fs.renameSync(next, file);
}

function readJson(file) {
  try {
    return JSON.parse(fs.readFileSync(file, "utf8"));
  } catch {
    return null;
  }
}

function sweepState(folder) {
  for (const name of fs.readdirSync(folder)) {
    const entry = path.join(folder, name);
    try {
      const stat = fs.lstatSync(entry);
      if (!stat.isDirectory() && Date.now() - stat.mtimeMs > STATE_MAX_AGE_MS) fs.unlinkSync(entry);
    } catch {
      // gone meanwhile, or not ours to remove
    }
  }
}

// ---- contracts: the copies under ./lib/contracts, all judged by the one engine in ./lib/contracts/lib -----------------------------

/** Every carried contract, loaded and validated by the shared engine. One that cannot be loaded is `broken` with its `error`: it claims every file, so it is reported. */
function contracts() {
  if (!fs.existsSync(CONTRACTS)) return [];
  return fs
    .readdirSync(CONTRACTS)
    .filter((name) => name !== "lib")
    .sort()
    .map((name) => ({ name, file: path.join(CONTRACTS, name, "scripts", "contract.json") }))
    .filter((entry) => fs.existsSync(entry.file))
    .map((entry) => {
      try {
        entry.engine = require(path.join(CONTRACTS, "lib", "engine.cjs"));
        entry.contract = entry.engine.loadContract(entry.file);
        entry.scope = entry.contract.scope ?? [];
        entry.globs = entry.scope.map((glob) => entry.engine.globRegex(glob));
      } catch (error) {
        entry.broken = true;
        entry.error = error;
      }
      return entry;
    });
}

/** The folders above a project-relative file, nearest first, up to the project root. */
function ancestors(rel) {
  const found = [];
  for (let dir = path.posix.dirname(rel); dir !== "." && dir !== "/"; dir = path.posix.dirname(dir)) found.push(dir);
  return found;
}

const matches = (entry, rel) => entry.globs.some((glob) => glob.test(rel));
/** Whether the contract could judge the file: it matches a scope glob, or sits in a folder that does. */
const claims = (entry, rel) => entry.broken === true || matches(entry, rel) || ancestors(rel).some((dir) => matches(entry, dir));

/** A written file as a project-relative slash path, or null outside the project. */
function relative(cwd, file) {
  const rel = posix(path.relative(cwd, path.resolve(cwd, file)));
  return rel === "" || rel.startsWith("..") || path.isAbsolute(rel) ? null : rel;
}

// ---- glob expansion for the shell scan ---------------------------------------------------------------

/** What `fn` returns, or `fallback` when it throws: an entry that cannot be read is skipped, never fatal. */
function attempt(fn, fallback) {
  try {
    return fn();
  } catch {
    return fallback;
  }
}
const statOf = (file) => attempt(() => fs.statSync(file, { throwIfNoEntry: false }), undefined);
const listOf = (dir, options) => attempt(() => fs.readdirSync(dir, options), []);

/** Every file below a folder, `.git` and `node_modules` left out. */
function filesBelow(dir) {
  const found = [];
  for (const entry of listOf(dir, { withFileTypes: true })) {
    if (entry.isDirectory()) {
      if (!SKIPPED_DIRS.has(entry.name)) found.push(...filesBelow(path.join(dir, entry.name)));
    } else found.push(path.join(dir, entry.name));
  }
  return found;
}

/** Folders under `dir`, itself included, `.git` and `node_modules` left out. */
function foldersBelow(dir) {
  const found = [dir];
  for (const entry of listOf(dir, { withFileTypes: true })) {
    if (entry.isDirectory() && !SKIPPED_DIRS.has(entry.name)) found.push(...foldersBelow(path.join(dir, entry.name)));
  }
  return found;
}

/** The files a scope glob names or holds, expanded segment by segment from its static prefix: `*` reads one folder, `**` walks below its prefix. */
function expand(root, glob, globRegex) {
  let found = [root];
  const segments = glob.split("/");
  for (const [index, segment] of segments.entries()) {
    const next = [];
    for (const dir of found) {
      if (!statOf(dir)?.isDirectory()) continue;
      // a trailing `**` is the folder itself: the final walk lists every file below it
      if (segment === "**") next.push(...(index === segments.length - 1 ? [dir] : foldersBelow(dir)));
      else if (!WILDCARD.test(segment)) next.push(path.join(dir, segment));
      else {
        const match = globRegex(segment);
        for (const name of listOf(dir)) if (match.test(name)) next.push(path.join(dir, name));
      }
    }
    found = next;
  }
  const files = [];
  const dirs = [];
  for (const entry of found) {
    const stat = statOf(entry);
    if (stat?.isDirectory()) dirs.push(entry);
    else if (stat) files.push(entry);
  }
  // `**` yields a folder and all its subfolders: walk only the outermost ones, so each file is listed once.
  const outer = [];
  for (const dir of dirs.sort()) if (!outer.some((top) => dir.startsWith(top + path.sep))) outer.push(dir);
  return [...files, ...outer.flatMap(filesBelow)];
}

/**
 * The files under the contracts' scope whose mtime is after `since`; each scope glob walked and each file read once.
 * A `"shell": false` contract keeps only the files whose project path one of `commands` names.
 */
function modifiedSince(cwd, entries, since, commands) {
  const text = commands.join("\n").replaceAll("\\", "/");
  const globs = new Set();
  const seen = new Set();
  const found = [];
  const named = (entry) => entry.contract.shell === false;
  // the contracts every shell turn scans walk first: a file they share with a named-only one is never dropped
  const usable = entries.filter((entry) => !entry.broken);
  for (const entry of [...usable.filter((e) => !named(e)), ...usable.filter(named)]) {
    if (named(entry) && text === "") continue;
    for (const glob of entry.scope) {
      if (globs.has(glob)) continue;
      globs.add(glob);
      for (const file of expand(cwd, glob, entry.engine.globRegex)) {
        if (seen.has(file)) continue;
        seen.add(file);
        if (statOf(file)?.mtimeMs > since && (!named(entry) || text.includes(relative(cwd, file)))) found.push(file);
      }
    }
  }
  return found;
}

// ---- goals --------------------------------------------------------------------------------------------

/** SessionStart: the reference time shell writes are told apart by. One already there stays: the session goes on (compaction, resume) and Stop renews it. */
function start(event) {
  const id = sessionOf(event);
  const folder = id && stateFolder(true);
  if (!folder) return;
  const ref = path.join(folder, `${id}${REF_SUFFIX}`);
  const stat = statOf(ref);
  if (stat === undefined || Date.now() - stat.mtimeMs > STATE_MAX_AGE_MS) writeAtomic(ref, String(Date.now()));
}

/** PostToolUse: notes the files the model wrote that some contract could claim, or the shell command it ran, in a mark of its own: calls running in parallel never share a file. */
function mark(event) {
  const id = sessionOf(event);
  if (!id) return;
  const shell = event.files.length === 0 && typeof event.command === "string";
  let files = [];
  if (event.files.length > 0) {
    const entries = contracts();
    files = event.files.map((file) => path.resolve(event.cwd, file.path)).filter((file) => {
      const rel = relative(event.cwd, file);
      return rel !== null && entries.some((entry) => claims(entry, rel));
    });
  }
  if (files.length === 0 && !shell) return;
  const folder = stateFolder(true);
  const mark = shell ? { files, shell, command: event.command } : { files, shell };
  if (folder) writeAtomic(path.join(folder, `${id}.${process.pid}-${crypto.randomBytes(6).toString("hex")}${MARK_SUFFIX}`), JSON.stringify(mark));
}

/** The session's marks, merged and removed: each one is read once and consumed. */
function takeMarks(folder, id) {
  const turn = { files: [], shell: false, commands: [] };
  let found = false;
  for (const name of listOf(folder)) {
    if (!name.startsWith(`${id}.`) || !name.endsWith(MARK_SUFFIX)) continue;
    const file = path.join(folder, name);
    const mark = readJson(file);
    attempt(() => fs.rmSync(file, { force: true }));
    if (mark === null) continue;
    found = true;
    if (Array.isArray(mark.files)) turn.files.push(...mark.files.filter((f) => typeof f === "string"));
    if (mark.shell === true) turn.shell = true;
    if (typeof mark.command === "string") turn.commands.push(mark.command);
  }
  return found ? turn : null;
}

/** Heads every non-empty answer: the model fixes the findings without rewriting what they do not name. */
const FIX_HINT = "These files break their AIDD contract. Fix each line below with a minimal edit; keep everything else as it is.";

/** The line of a failure that stops a contract from judging, never silenced. */
const brokenLine = (entry, error) => `${entry.name}: ${String(error?.message ?? error).split("\n")[0]}`;

/** The units of one written file that the contract claims: the file, or the nearest folder of a scope glob holding the marker. */
function unitsOf(contract, globs, cwd, rel) {
  if (contract.unit === "file") return globs.some((glob) => glob.test(rel)) ? [path.join(cwd, rel)] : [];
  const folder = ancestors(rel).find((dir) => globs.some((glob) => glob.test(dir)) && fs.existsSync(path.join(cwd, dir, contract.marker)));
  return folder === undefined ? [] : [path.join(cwd, folder)];
}

/** Judges the written files by their contracts; one line per finding on a written file, one per broken contract. */
function judge(cwd, entries, written) {
  const lines = new Set();
  const done = new Set();
  for (const file of written) {
    const rel = relative(cwd, file);
    if (rel === null || !fs.existsSync(file)) continue;
    for (const entry of entries) {
      if (!claims(entry, rel)) continue;
      if (entry.broken) {
        lines.add(brokenLine(entry, entry.error));
        continue;
      }
      try {
        for (const target of unitsOf(entry.contract, entry.globs, cwd, rel)) {
          if (done.has(`${entry.name}\0${target}`)) continue;
          done.add(`${entry.name}\0${target}`);
          for (const found of entry.engine.check(entry.contract, target)) {
            if (written.has(found.path)) lines.add(`${posix(path.relative(cwd, found.path))}:${found.line} ${found.id} ${found.message}`);
          }
        }
      } catch (error) {
        lines.add(`${rel}: ${brokenLine(entry, error)}`);
      }
    }
  }
  if (lines.size === 0) return "";
  const shown = [...lines].slice(0, MAX_LINES);
  const more = lines.size - shown.length;
  return [FIX_HINT, ...shown, ...(more > 0 ? [`+${more} more: run the skill's validate script`] : [])].join("\n");
}

/**
 * Stop: the findings on the files the turn wrote, "" when there are none. Consumes the mark, never creates
 * state, and renews the reference time. A turn that already continued is silenced by host.continueTurn.
 */
function atStop(event) {
  const id = sessionOf(event);
  const folder = id && stateFolder(false);
  if (!folder) return "";
  const refFile = path.join(folder, `${id}${REF_SUFFIX}`);
  try {
    sweepState(folder);
    const turn = takeMarks(folder, id);
    if (turn === null) return "";
    const entries = contracts();
    const written = new Set(turn.files.map((f) => path.resolve(f)));
    const since = Number(attempt(() => fs.readFileSync(refFile, "utf8"), Number.NaN));
    // a shell scan that fails must not lose the files the model's own writes marked
    if (turn.shell && Number.isFinite(since)) for (const file of attempt(() => modifiedSince(event.cwd, entries, since, turn.commands), [])) written.add(file);
    return judge(event.cwd, entries, written);
  } finally {
    try {
      writeAtomic(refFile, String(Date.now()));
    } catch {
      // the reference is only an optimisation of the next turn
    }
  }
}

function main(goal) {
  try {
    const event = host.readEvent();
    if (event === undefined) return;
    if (goal === "start" && event.event === "SessionStart") start(event);
    else if (goal === "mark" && event.event === "PostToolUse") mark(event);
    else if (goal === "check" && event.event === "Stop") host.continueTurn(atStop(event));
  } catch {
    // a broken check never fails the turn
  }
}

module.exports = { atStop };

if (require.main === module) {
  main(process.argv[2]);
  process.exitCode = 0;
}
